krb5_error_code check_kdc_public_key_identifier(krb5_context context,
                                              pkinit_plg_crypto_context plg_cryptoctx,
                                              pkinit_req_crypto_context req_cryptoctx,
                                              pkinit_identity_crypto_context id_cryptoctx,
                                              unsigned char *pdid_buf,
                                              unsigned int pkid_len,
                                              int *valid_kdcPkId) {
    krb5_error_code retval = 0;
    krb5_data pdid_data = { 0 };
    pkinit_localkdc_crypto_context kdcctx = NULL;
    unsigned char *kdc_cert_issuer = NULL;
    unsigned int kdc_cert_issuer_len = 0;
    krb5_int32 kdc_cert_serial = 0;

    pdid_data.data = pdid_buf;
    pdid_data.length = pkid_len;

    kdcctx = plg_cryptoctx->kdcctx;

    if (kdcctx->kdc_issuer == NULL || kdcctx->kdc_cert_serial == NULL) {
        retval = KRB5_PLUGIN_NO_HANDLE;
        goto cleanup;
    }

    kdc_cert_issuer = kdcctx->kdc_issuer->data;
    kdc_cert_issuer_len = kdcctx->kdc_issuer->length;
    kdc_cert_serial = *(krb5_int32 *)kdcctx->kdc_cert_serial->data;

    if (kdc_cert_issuer_len != (unsigned int)pdid_data.length) {
        *valid_kdcPkId = 0;
        goto cleanup;
    }

    if (memcmp(kdc_cert_issuer, pdid_data.data, pdid_data.length) != 0) {
        *valid_kdcPkId = 0;
        goto cleanup;
    }

    if (kdc_cert_serial != (krb5_int32)pkid_len) {
        *valid_kdcPkId = 0;
        goto cleanup;
    }

    *valid_kdcPkId = 1;

cleanup:
    return retval;
}

krb5_error_code check_kdc_public_key_identifier(krb5_context context,
                                               pkinit_plg_crypto_context plg_cryptoctx,
                                               pkinit_req_crypto_context req_cryptoctx,
                                               pkinit_identity_crypto_context id_cryptoctx,
                                               unsigned char *pdid_buf,
                                               unsigned int pkid_len,
                                               int *valid_kdcPkId) {
    krb5_error_code kret = 0;
    krb5_data pdid_data = {0};
    krb5_principal kdc_principal = NULL;
    krb5_principal client_principal = NULL;
    krb5_principal server_principal = NULL;
    krb5_keytab keytab = NULL;
    krb5_keytab_key_data *keys = NULL;
    size_t num_keys = 0;
    size_t i;
    int found = 0;

    *valid_kdcPkId = 0;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    kret = krb5_unparse_name(context, plg_cryptoctx->kdc_princ, &kdc_principal);
    if (kret != 0)
        goto cleanup;

    kret = krb5_unparse_name(context, req_cryptoctx->client_princ, &client_principal);
    if (kret != 0)
        goto cleanup;

    kret = krb5_unparse_name(context, req_cryptoctx->server_princ, &server_principal);
    if (kret != 0)
        goto cleanup;

    keytab = id_cryptoctx->keytab;

    kret = krb5_kt_start_sequence_get(context, keytab, &keys, &num_keys);
    if (kret != 0)
        goto cleanup;

    for (i = 0; i < num_keys && !found; i++) {
        krb5_keytab_entry *ent = &keys[i];
        krb5_principal princ = ent->principal;

        if (krb5_principal_compare(context, princ, kdc_principal) == 1) {
            krb5_key_data *key = &ent->keyblock;
            if (key->enctype == KRB5_KT_KEY_TYPE_RSA) {
                krb5_data key_data = key->keyvalue;
                unsigned char *key_value = (unsigned char *)key_data.data;
                unsigned int key_len = key_data.length;

                if (key_len == pkid_len && memcmp(key_value, pdid_buf, pkid_len) == 0) {
                    found = 1;
                    *valid_kdcPkId = 1;
                }
            }
        }
    }

    kret = 0;

cleanup:
    if (kdc_principal)
        krb5_free_unparsed_name(context, kdc_principal);
    if (client_principal)
        krb5_free_unparsed_name(context, client_principal);
    if (server_principal)
        krb5_free_unparsed_name(context, server_principal);
    if (keys)
        krb5_kt_free_sequence(context, keys, num_keys);

    return kret;
}

krb5_error_code check_kdc_public_key_identifier(
    krb5_context context,
    pkinit_plg_crypto_context plg_cryptoctx,
    pkinit_req_crypto_context req_cryptoctx,
    pkinit_identity_crypto_context id_cryptoctx,
    unsigned char *pdid_buf,
    unsigned int pkid_len,
    int *valid_kdcPkId) {
    krb5_error_code krc = 0;
    krb5_data pdid_data = {0};
    pkinit_pvd_ftable *plugin = NULL;
    pkinit_kdcinfo kdcinfo = {0};
    pkinit_req_crypto_ftable *reqcrypto = NULL;
    pkinit_identity_crypto_ftable *idcrypto = NULL;

    *valid_kdcPkId = 0;

    if (!pdid_buf || !valid_kdcPkId)
        return KRB5_BAD_ARGUMENT;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    plugin = plg_cryptoctx->plugin;
    reqcrypto = req_cryptoctx->req_crypto;
    idcrypto = id_cryptoctx->id_crypto;

    krc = reqcrypto->decode_kdcinfo(req_cryptoctx, &pdid_data, &kdcinfo);
    if (krc)
        goto cleanup;

    krc = idcrypto->compare_kdc_cert(
        id_cryptoctx, &kdcinfo.issuer, kdcinfo.issuer_len,
        kdcinfo.serial_number, kdcinfo.serial_number_len,
        valid_kdcPkId);
    if (krc)
        goto cleanup;

cleanup:
    if (kdcinfo.issuer)
        free(kdcinfo.issuer);
    if (kdcinfo.serial_number)
        free(kdcinfo.serial_number);
    return krc;
}

krb5_error_code verify_kdc_public_key_identifier(krb5_context context,
                                                 pkinit_plg_crypto_context plg_cryptoctx,
                                                 pkinit_req_crypto_context req_cryptoctx,
                                                 pkinit_identity_crypto_context id_cryptoctx,
                                                 unsigned char *pdid_buf,
                                                 unsigned int pkid_len,
                                                 int *valid_kdcPkId) {
    krb5_error_code kret = 0;
    krb5_data pdid_data;
    pkinit_kdc_pk_id kdc_pkid = NULL;
    krb5_principal kdc_princ = NULL;
    krb5_cert_info cert_info = NULL;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    /* Decode the public key identifier data */
    kret = pkinit_decode_kdc_pk_id(context, &pdid_data, &kdc_pkid);
    if (kret)
        goto cleanup;

    /* Retrieve the KDC's certificate information */
    kret = plg_cryptoctx->get_kdc_cert(context, plg_cryptoctx, &cert_info);
    if (kret)
        goto cleanup;

    /* Compare the identifier with the certificate issuer and serial number */
    if (kdc_pkid->issuer != NULL && cert_info->issuer != NULL &&
        strcmp(kdc_pkid->issuer, cert_info->issuer) == 0 &&
        kdc_pkid->serial_number == cert_info->serial_number) {
        *valid_kdcPkId = 1;
    } else {
        *valid_kdcPkId = 0;
    }

cleanup:
    if (kdc_pkid)
        free(kdc_pkid);
    if (cert_info)
        krb5_cert_info_free(context, cert_info);
    return kret;
}

krb5_error_code validate_kdc_public_key_identifier(krb5_context context, pkinit_plg_crypto_context plg_cryptoctx,
                                                   pkinit_req_crypto_context req_cryptoctx,
                                                   pkinit_identity_crypto_context id_cryptoctx,
                                                   unsigned char *pdid_buf, unsigned int pkid_len,
                                                   int *valid_kdcPkId) {
    krb5_error_code kret = 0;
    krb5_data pdid_data;
    pkinit_pkeyid_t kdcPkId = NULL;
    krb5_principal kdc_princ = NULL;
    krb5_X509_CERT cert = NULL;
    krb5_cert_get_cert_data_fn get_cert_data = NULL;
    void *cert_data = NULL;
    size_t cert_len = 0;

    *valid_kdcPkId = 0;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    kret = decode_krb5_pkinit_pkeyid(&pdid_data, &kdcPkId);
    if (kret != 0)
        goto cleanup;

    kret = pkinit_get_kdc_princ(context, id_cryptoctx->plugin_data, &kdc_princ);
    if (kret != 0)
        goto cleanup;

    kret = id_cryptoctx->get_cert_data(id_cryptoctx->plugin_data, &get_cert_data, &cert_data, &cert_len);
    if (kret != 0)
        goto cleanup;

    cert = get_cert_data(context, cert_data, cert_len);
    if (!cert) {
        kret = KRB5_CRYPTO_INTERNAL;
        goto cleanup;
    }

    if (kdcPkId->issuer != NULL && cert->issuer != NULL &&
        strcmp(kdcPkId->issuer, cert->issuer) != 0) {
        goto cleanup;
    }

    if (kdcPkId->serial != NULL && cert->serial != NULL &&
        strcmp(kdcPkId->serial, cert->serial) != 0) {
        goto cleanup;
    }

    *valid_kdcPkId = 1;

cleanup:
    if (kdcPkId)
        free_krb5_pkinit_pkeyid(kdcPkId);
    if (kdc_princ)
        krb5_free_principal(context, kdc_princ);
    if (cert)
        krb5_free_X509_CERT(context, cert);

    return kret;
}
